// Serves the LATEST advisory local-LLM code-review report. Read-only.
// The report is produced by scripts/orchestration/llm-review.mjs (qwen2.5 on
// the NAS reviews a branch's DIFF) and written to the bind-mount path below.
// This node just reads that file and serves it; it runs NO model itself.
//
// ADVISORY: the payload always carries advisory:true. The merge gate is
// deterministic CI (lint + vitest), never this. HONEST OFFLINE (DR-0076): if no
// report exists yet, return ok:false with how to generate one -- never a fake
// "all clear". Mirrors wf-llm-health's shape + bearer gate.
//
// REPORT_FILE: where llm-review.mjs writes with
//   --out /data/poetech-briefing/_llm_review.json
// (the same poetech-briefing bind mount the dispatch reel uses). Adjust if the
// orchestrator writes elsewhere.

const fs = require('fs');

const REPORT_FILE = '/data/poetech-briefing/_llm_review.json';
const BEARER_FILE = '/home/node/.n8n/n8n-webhook-bearer.txt';
const STALE_MS = 7 * 24 * 60 * 60 * 1000; // older than a week reads as stale

function readSecret(p) {
  try { return fs.readFileSync(p, 'utf8').trim(); } catch (e) { return ''; }
}

const input = $input.first().json || {};
const headers = (input.headers && typeof input.headers === 'object') ? input.headers : {};

// Bearer gate (defense in depth; the NAS being LAN/Funnel-only is the real
// boundary). If no bearer file exists, the check is skipped.
const expected = readSecret(BEARER_FILE);
const auth = String(headers.authorization || headers.Authorization || '');
const presented = auth.replace(/^Bearer\s+/i, '').trim();
if (expected && presented !== expected) {
  return [{ json: { ok: false, error: 'unauthorized' } }];
}

let raw;
try {
  raw = fs.readFileSync(REPORT_FILE, 'utf8');
} catch (e) {
  return [{ json: { ok: false, error: 'no review yet -- run scripts/orchestration/llm-review.sh with --out ' + REPORT_FILE } }];
}

let report;
try {
  report = JSON.parse(raw);
} catch (e) {
  return [{ json: { ok: false, error: 'review report is not valid JSON' } }];
}

// Pass the report through untouched (the app's normalizeLlmReview owns shaping),
// but stamp staleness honestly so a long-ago review isn't read as current.
const gen = report && report.generated_at ? Date.parse(report.generated_at) : NaN;
if (Number.isFinite(gen) && (Date.now() - gen) > STALE_MS) {
  report.stale = true;
}
report.served_at = new Date().toISOString();
report.advisory = true;

return [{ json: report }];
